import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        if ttl <= 0:
            raise ValueError("ttl must be positive")
        self._capacity = capacity
        self._ttl = ttl
        self._clock = clock
        self._store: OrderedDict = OrderedDict()  # key -> (value, set_time)

    def _is_expired(self, set_time: float) -> bool:
        return self._clock() - set_time >= self._ttl

    def get(self, key, default=None):
        if key not in self._store:
            return default
        value, set_time = self._store[key]
        if self._is_expired(set_time):
            return default
        self._store.move_to_end(key)
        return value

    def set(self, key, value):
        now = self._clock()
        self._store[key] = (value, now)
        self._store.move_to_end(key)
        if len(self._store) > self._capacity:
            # Drop all expired entries first
            expired = [k for k, (_, t) in self._store.items() if self._is_expired(t)]
            for k in expired:
                del self._store[k]
            # Evict LRU entries if still over capacity
            while len(self._store) > self._capacity:
                self._store.popitem(last=False)

    def __len__(self) -> int:
        now = self._clock()
        return sum(1 for (_, t) in self._store.values() if now - t < self._ttl)

    def delete(self, key) -> bool:
        if key not in self._store:
            return False
        _, set_time = self._store[key]
        if self._is_expired(set_time):
            return False
        del self._store[key]
        return True
